#!/usr/bin/env node
/**
 * Agent pack release builder (dmtools-agents#441).
 *
 * Computes the affected agent set from the git diff since the last release,
 * bumps each affected agent's version in versions.json, builds EVERY agent
 * pack with `dmtools compile` (the single implementation of the pack format —
 * dm.ai#595), validates each zip against its manifest, and writes a FULL
 * catalog.json (every agent -> its current version): each release is a
 * self-contained snapshot because the registry resolver resolves
 * `<agent>@latest` against the newest release's catalog only.
 *
 * Usage:
 *   node ci/release_packs.mjs [--agents=all|name1,name2] [--bump=patch|minor|major]
 *       [--base-ref <git-ref>] [--out dist] [--dry-run]
 *
 * Exit 0 with an empty affected set means "nothing to release" (not an error).
 */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync,
  copyFileSync, cpSync, chmodSync, mkdtempSync, rmSync, statSync, utimesSync,
} from 'node:fs';
import { basename, dirname, join, resolve, sep } from 'node:path';
import { tmpdir } from 'node:os';
import { execSync } from 'node:child_process';

// Pack launch-surface contract (Wave 2, owner 2026-10-01): teammate packs
// carry launch.json (+ loop/verdict.sh for review packs) inside the zip.
import { launchExtras, mergeManifest } from './pack_launch_contract.cjs';

// Release-guard classification (gh-690): versions.json is the version
// LEDGER — data, not an agent. The old inline filter in allAgents() swept it
// in as a phantom "versions" agent (a bogus ledger key plus a phantom
// versions-<v>.zip in every release).
import { agentNamesFromFiles, isLedgerFile } from './pack_release_guard.cjs';

const ROOT = process.cwd();
const VERSIONS_FILE = join(ROOT, 'versions.json');
const OUT_DIR = arg('--out') || 'dist';
const BUMP = arg('--bump') || 'patch';
const AGENTS_INPUT = arg('--agents') || '';
const BASE_REF = arg('--base-ref') || '';
const DRY_RUN = hasFlag('--dry-run');

/** Directory prefixes whose change affects every agent (shared runtime code). */
const SHARED_PREFIXES = ['js/', 'instructions/', 'prompts/', 'scripts/'];

/**
 * The factory-setup asset (owner mandate 2026-10-03: "no factory-agents tree
 * checkout in the factory") — the workflow glue the factory needs at run
 * time, shipped as a release zip so awf's factory-teammate.yml never clones
 * the dmtools-agents tree:
 *   setup/    — the whole toolbelt (install.sh, cache.sh, review-verdict.sh,
 *               fa-session.sh, per-tool installers, _common.sh)
 *   scripts/git-push-guard.sh — the guard fallback (kit stays primary)
 *   configs/  — the four leg entry configs the guard job names as its
 *               parent-config fallback (pack launch.json stays primary)
 */
const FACTORY_SETUP_LEGS = ['bug_development', 'story_development', 'pr_review', 'pr_rework'];

/** True when any changed file lives under setup/ or the builder itself. */
function setupTouched() {
  if (AGENTS_INPUT) return true; // explicit dispatch: always ship a fresh asset
  const changed = changedFiles();
  if (changed === null) return true;
  // setup/ content or THIS builder — either way the factory-setup asset
  // must re-ship (live: the builder-only diff cut no release and the
  // factory-setup asset never landed, 2026-10-03).
  return changed.some((f) => f.startsWith('setup/') || f === 'ci/release_packs.mjs');
}

/** Builds dist/factory-setup-<datestamp>.zip + .sha256 sidecar. */
function buildFactorySetup() {
  const stamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14); // YYYYMMDDHHMMSS
  mkdirSync(OUT_DIR, { recursive: true });
  const zipPath = resolve(OUT_DIR, `factory-setup-${stamp}.zip`);
  const staging = mkdtempSync(join(tmpdir(), 'factory-setup-'));
  try {
    mkdirSync(join(staging, 'configs'), { recursive: true });
    cpSync(join(ROOT, 'setup'), join(staging, 'setup'), { recursive: true });
    mkdirSync(join(staging, 'scripts'), { recursive: true });
    copyFileSync(join(ROOT, 'scripts', 'git-push-guard.sh'), join(staging, 'scripts', 'git-push-guard.sh'));
    for (const leg of FACTORY_SETUP_LEGS) {
      copyFileSync(join(ROOT, `${leg}.json`), join(staging, 'configs', `${leg}.json`));
    }
    // Plain integrity inventory (not a dmtools agent-pack manifest — this is
    // workflow glue, never resolved by the agent pack registry).
    const sums = [];
    const walk = (dir, rel) => {
      for (const e of readdirSync(dir, { withFileTypes: true })) {
        const relPath = rel ? `${rel}/${e.name}` : e.name;
        if (e.isDirectory()) walk(join(dir, e.name), relPath);
        else sums.push(`${createHash('sha256').update(readFileSync(join(dir, e.name))).digest('hex')}  ${relPath}`);
      }
    };
    walk(staging, '');
    writeFileSync(join(staging, 'SHA256SUMS'), `${sums.sort().join('\n')}\n`);
    execSync(`cd ${JSON.stringify(staging)} && zip -q -r ${JSON.stringify(zipPath)} .`);
    const digest = createHash('sha256').update(readFileSync(zipPath)).digest('hex');
    writeFileSync(`${zipPath}.sha256`, `${digest}  ${basename(zipPath)}\n`);
    console.log(`built ${basename(zipPath)} (${sums.length} files)`);
  } finally {
    rmSync(staging, { recursive: true, force: true });
  }
  return zipPath;
}

function arg(name) {
  // Support both "--flag value" and "--flag=value".
  const eq = process.argv.find((a) => a.startsWith(`${name}=`));
  if (eq) return eq.slice(name.length + 1);
  const i = process.argv.indexOf(name);
  return i >= 0 && i + 1 < process.argv.length ? process.argv[i + 1] : null;
}

function hasFlag(name) {
  return process.argv.includes(name);
}

function readVersions() {
  return JSON.parse(readFileSync(VERSIONS_FILE, 'utf8'));
}

/** All root-level *.json entry points (agent names), excluding package*.json
 *  and the versions.json ledger (gh-690 — see ci/pack_release_guard.cjs). */
function allAgents() {
  return agentNamesFromFiles(readdirSync(ROOT));
}

/** Files changed since the base ref (last release tag), or all when none. */
function changedFiles() {
  if (!BASE_REF) return null; // caller treats null as "unknown -> all agents"
  try {
    const out = execSync(`git diff --name-only ${BASE_REF}...HEAD`, { cwd: ROOT, encoding: 'utf8' });
    return out.split('\n').map((s) => s.trim()).filter(Boolean);
  } catch (e) {
    console.warn(`git diff against ${BASE_REF} failed (${e.message}); releasing all agents`);
    return null;
  }
}

/**
 * Affected set: changed root entry configs, plus every agent when any shared
 * runtime file changed (conservative superset of the closure intersection —
 * never misses an affected agent).
 */
function computeAffectedSet() {
  if (AGENTS_INPUT === 'all') return allAgents();
  if (AGENTS_INPUT) return AGENTS_INPUT.split(',').map((s) => s.trim()).filter(Boolean);

  const changed = changedFiles();
  if (changed === null) return allAgents();

  const affected = new Set();
  for (const file of changed) {
    if (isLedgerFile(file)) continue; // ledger churn marks nothing affected (gh-690)
    if (file.endsWith('.json') && !file.includes('/') && !file.startsWith('package')) {
      affected.add(basename(file, '.json')); // a root entry config changed
    }
    if (SHARED_PREFIXES.some((p) => file.startsWith(p))) {
      console.log(`Shared file changed: ${file} — bumping all agents`);
      return allAgents();
    }
  }
  return [...affected].sort();
}

/** Semver bump. */
function bump(version, kind) {
  const [maj, min, pat] = version.split('.').map((n) => parseInt(n, 10) || 0);
  if (kind === 'major') return `${maj + 1}.0.0`;
  if (kind === 'minor') return `${maj}.${min + 1}.0`;
  return `${maj}.${min}.${pat + 1}`;
}

/**
 * Adds the launch surface (see ci/pack_launch_contract.cjs) to a compiled
 * pack zip: unpack → copy the contract files in (verbatim) → fold them
 * into manifest.json (sorted, sha256, mode) → rebuild the zip
 * deterministically (manifest first, sorted entries, fixed 1980-01-01
 * mtime — compiler parity) → refresh the .sha256 sidecar. Non-teammate
 * packs pass through untouched.
 */
function augm…

/**
 * Unit tests: the pack-release pipeline (ci/release_packs.mjs +
 * .github/workflows/agent-pack-release.yml + ci/pack_release_guard.cjs).
 *
 * Guards the gh-690 incident class (live 2026-10-04 05:40-05:48): three
 * content PRs merged within 3 minutes → three overlapping release runs →
 * THREE ledger bump PRs, of which #689 MERGED WITH A 0-BYTE DIFF (its branch
 * was cut before #688's identical ledger landed; `gh pr merge --auto` fires
 * server-side the moment checks pass and cannot re-verify that main did not
 * move in between). The same stale-checkout race double-bumped the agents
 * whose content landed mid-flight (sm_github/pr_review 0.1.24 vs 0.1.23).
 *
 * Invariants:
 *   R1 ledger sweep — versions.json is the version LEDGER (data), never an
 *      agent: agent discovery and the affected-set computation must exclude
 *      it (the old sweep built a phantom versions-*.zip, shipped it in every
 *      release, and wrote a bogus "versions" key into the ledger).
 *   R2 nothing-changed guard — a ledger bump PR whose versions.json already
 *      matches main must be CLOSED (or never created), never merged.
 *   R3 queued runs release CURRENT main — a run queued behind another must
 *      reset to origin/main before computing the affected set, so content
 *      that landed mid-queue is released exactly once from the current
 *      ledger (no duplicate releases, no off-by-one bumps).
 *   R4 single trigger plane — the concurrency group serializes release
 *      runs (present since #441; pinned here so it cannot silently vanish).
 *
 * Uses: loadModule(), file_read(), suite(), test(), assert
 */

'use strict';

/* global loadModule, assert, test, suite, file_read */

function guard() {
    return loadModule('ci/pack_release_guard.cjs');
}

function nthIndexOf(haystack, needle, n) {
    var i = -1;
    for (var k = 0; k < n; k++) {
        i = haystack.indexOf(needle, i + 1);
        if (i === -1) return -1;
    }
    return i;
}

// ── R1: the ledger is data, not an agent ─────────────────────────────────────

suite('pack release guard: file classification', function () {

    test('the version ledger is recognized', function () {
        assert.equal(guard().isLedgerFile('versions.json'), true);
        assert.equal(guard().LEDGER_FILE, 'versions.json');
    });

    test('agent configs and unrelated files are not the ledger', function () {
        assert.equal(guard().isLedgerFile('sm.json'), false);
        assert.equal(guard().isLedgerFile('package.json'), false);
        assert.equal(guard().isLedgerFile('js/versions.json'), false,
            'only the repo-root ledger counts');
    });

    test('a root entry config is an agent config', function () {
        assert.equal(guard().isAgentConfigFile('sm.json'), true);
        assert.equal(guard().isAgentConfigFile('createRepoTasks.json'), true);
    });

    test('the ledger is NOT an agent config (gh-690 R1)', function () {
        assert.equal(guard().isAgentConfigFile('versions.json'), false,
            'the old allAgents() sweep treated versions.json as an agent named ' +
            '"versions" — a phantom pack in every release and a bogus ledger key');
    });

    test('npm metadata and nested files are not agent configs', function () {
        assert.equal(guard().isAgentConfigFile('package.json'), false);
        assert.equal(guard().isAgentConfigFile('package-lock.json'), false);
        assert.equal(guard().isAgentConfigFile('js/sm.json'), false,
            'agent entry configs live at the repo root only');
        assert.equal(guard().isAgentConfigFile('instructions/x.json'), false);
    });

    test('toAgentName strips only the .json suffix', function () {
        assert.equal(guard().toAgentName('sm.json'), 'sm');
        assert.equal(guard().toAgentName('createRepoTasks.json'), 'createRepoTasks');
    });

    test('agentNamesFromFiles maps a multi-file listing to sorted agent names', function () {
        var names = guard().agentNamesFromFiles([
            'story_development.json', 'versions.json', 'package.json',
            'sm.json', 'js/helpers.json', 'README.md',
        ]);
        assert.deepEqual(names, ['sm', 'story_development'],
            'the ledger, npm metadata and non-root files are all excluded');
    });

    test('an empty listing yields an empty agent set', function () {
        assert.deepEqual(guard().agentNamesFromFiles(['versions.json', 'package.json']), []);
    });
});

// ── release builder wiring (ci/release_packs.mjs) ────────────────────────────

suite('release builder wiring', function () {

    var builder = file_read({ path: 'ci/release_packs.mjs' });

    test('the builder imports the guard module', function () {
        assert.ok(builder.indexOf('pack_release_guard.cjs') !== -1,
            'ci/release_packs.mjs must import ci/pack_release_guard.cjs');
    });

    test('agent discovery goes through the ledger-aware classifier', function () {
        assert.ok(builder.indexOf('agentNamesFromFiles(readdirSync(ROOT))') !== -1,
            'allAgents() must classify via agentNamesFromFiles — the old inline ' +
            'filter swept versions.json in as a phantom "versions" agent');
    });

    test('a changed ledger file never marks anything affected', function () {
        var affected = builder.indexOf('function computeAffectedSet()');
        var skip = builder.indexOf('isLedgerFile', affected);
        assert.ok(skip !== -1,
            'computeAffectedSet must skip the ledger: every merged ledger PR ' +
            'puts versions.json into the base...HEAD diff, and the old sweep ' +
            'turned that into a phantom affected agent');
    });

    test('the builder still wires the launch contract', function () {
        assert.ok(builder.indexOf('pack_launch_contract.cjs') !== -1,
            'gh-690 must not regress the dm.ai#595 launch surface wiring');
    });
});

// ── release workflow wiring (agent-pack-release.yml) ─────────────────────────

suite('release workflow wiring', function () {

    var wf = file_read({ path: '.github/workflows/agent-pack-release.yml' });

    test('R4: the concurrency group serializes release runs', function () {
